const open=new Promise((resolve,reject)=>{const req=indexedDB.open('aincrad-studio-v1',1);req.onupgradeneeded=()=>{for(const s of ['meta','floors','assets','images'])req.result.createObjectStore(s);};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
export async function get(store,key){const db=await open;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function put(store,key,value){const db=await open;return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(value,key);t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Gravação cancelada.'));});}
export async function all(store){const db=await open;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function replaceProject(project,floors,assets,images){const db=await open;return new Promise((resolve,reject)=>{const t=db.transaction(['meta','floors','assets','images'],'readwrite');for(const s of ['meta','floors','assets','images'])t.objectStore(s).clear();t.objectStore('meta').put(project,'project');for(const [s,rows]of [['floors',floors],['assets',assets],['images',images]])for(const row of rows)t.objectStore(s).put(row,row.id);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Falha ao restaurar; projeto anterior preservado.'));});}
